try {
  const rawInput = $input.first();
  const item = rawInput.json;
  const body = item.body || item;
  const headers = item.headers || {};

  // Gắn correlation ID để phục vụ việc truy vết luồng xử lý
  const correlationId = headers['x-correlation-id'] || `jira_push_${Date.now()}`;

  return [{
    json: {
      step: 2,
      stepName: 'Security & Header Inspector',
      success: true,
      correlationId,
      timestamp: new Date().toISOString(),
      receivedHeaders: {
        host: headers.host || 'localhost',
        contentType: headers['content-type'] || 'application/json'
      },
      body
    }
  }];
} catch (err) {
  return [{
    json: {
      step: 2,
      success: false,
      error: `Security Check Error: ${err.message}`
    }
  }];
}

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const body = item.body || {};
const { jiraDomain, jiraEmail, jiraApiToken, projectKey } = body;

const errors = [];
if (!jiraDomain || typeof jiraDomain !== 'string' || !jiraDomain.trim()) {
  errors.push('Thiếu hoặc sai định dạng jiraDomain');
}
if (!jiraEmail || typeof jiraEmail !== 'string' || !jiraEmail.includes('@')) {
  errors.push('Thiếu hoặc sai định dạng email Jira');
}
if (!jiraApiToken || typeof jiraApiToken !== 'string') {
  errors.push('Thiếu Jira API Token');
}
if (!projectKey || typeof projectKey !== 'string') {
  errors.push('Thiếu projectKey (mã dự án Jira)');
}

if (errors.length > 0) {
  return [{
    json: {
      step: 3,
      stepName: 'Jira Connection Validator',
      success: false,
      errorMessage: errors.join('; '),
      errors,
      ...item
    }
  }];
}

return [{
  json: {
    step: 3,
    stepName: 'Jira Connection Validator',
    success: true,
    validatedCredentials: {
      jiraDomain: jiraDomain.trim(),
      jiraEmail: jiraEmail.trim(),
      jiraApiToken,
      projectKey: projectKey.trim().toUpperCase()
    },
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { epics } = item.body || {};

if (!Array.isArray(epics) || epics.length === 0) {
  return [{
    json: {
      step: 4,
      stepName: 'Epics Structure Validator',
      success: false,
      errorMessage: 'Danh sách epics rỗng. Vui lòng phân tích yêu cầu trước khi đẩy lên Jira!',
      ...item
    }
  }];
}

// Chuẩn hóa cấu trúc epics và gán ID nội bộ nếu thiếu
const sanitizedEpics = epics.map((epic, eIdx) => {
  const stories = epic.stories || epic.user_stories || [];
  return {
    ...epic,
    title: (epic.title || epic.summary || `Epic ${eIdx + 1}`).trim(),
    description: (epic.description || epic.title || '').trim(),
    stories: stories.map((story, sIdx) => {
      const tasks = story.tasks || story.subtasks || [];
      return {
        ...story,
        title: (story.title || story.summary || `Story ${sIdx + 1}`).trim(),
        description: (story.description || story.title || '').trim(),
        tasks: tasks.map((task, tIdx) => {
          const taskTitle = typeof task === 'string' ? task : (task.title || task.summary || `Task ${tIdx + 1}`);
          const taskDesc = typeof task === 'object' ? (task.description || taskTitle) : taskTitle;
          return {
            title: taskTitle.trim(),
            description: taskDesc.trim(),
            assigneeId: typeof task === 'object' ? task.assigneeId : null,
            assigneeName: typeof task === 'object' ? task.assigneeName : null
          };
        })
      };
    })
  };
});

return [{
  json: {
    step: 4,
    stepName: 'Epics Structure Validator',
    success: true,
    sanitizedEpics,
    totalEpicsToCreate: sanitizedEpics.length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { jiraDomain, jiraEmail, jiraApiToken, projectKey } = item.validatedCredentials;

// Làm sạch domain: bỏ dấu gạch chéo cuối và query params
const cleanDomain = jiraDomain.split('?')[0].replace(/\/+$/, '');

// Tạo Basic Auth Token chuẩn RFC 7617
const authString = `${jiraEmail}:${jiraApiToken}`;
const authHeader = 'Basic ' + Buffer.from(authString).toString('base64');

const requestHeaders = {
  'Authorization': authHeader,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};

return [{
  json: {
    step: 5,
    stepName: 'Domain & Basic Auth Normalizer',
    success: true,
    cleanDomain,
    authHeader,
    requestHeaders,
    projectKey,
    apiUrl: `${cleanDomain}/rest/api/2/issue`,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { cleanDomain, requestHeaders, projectKey, sanitizedEpics } = item;
const createdEpics = [];

for (const epic of sanitizedEpics) {
  const epicTitle = epic.title || 'Untitled Epic';
  const epicDesc = epic.description || epicTitle;

  const epicPayload = {
    fields: {
      project: { key: projectKey },
      summary: epicTitle,
      description: epicDesc,
      issuetype: { name: 'Epic' }
    }
  };

  let resData;
  try {
    const res = await fetch(`${cleanDomain}/rest/api/2/issue`, {
      method: 'POST',
      headers: requestHeaders,
      body: JSON.stringify(epicPayload)
    });
    resData = await res.json().catch(() => ({}));
    if (!res.ok) {
      const errMsg = resData.errorMessages?.join(', ') || JSON.stringify(resData.errors || resData);
      throw new Error(`Jira API (${res.status}): ${errMsg}`);
    }
  } catch (err) {
    return [{
      json: {
        step: 6,
        stepName: 'Epic Creation Engine',
        success: false,
        errorMessage: `Lỗi khi tạo Epic "${epicTitle}": ${err.message}`,
        ...item
      }
    }];
  }

  createdEpics.push({
    originalEpic: epic,
    epicKey: resData.key,
    epicId: resData.id,
    title: epicTitle,
    url: `${cleanDomain}/browse/${resData.key}`
  });
}

return [{
  json: {
    step: 6,
    stepName: 'Epic Creation Engine',
    success: true,
    createdEpics,
    epicsCount: createdEpics.length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { createdEpics } = item;
const pendingStories = [];

// Ánh xạ từng Story với Epic cha tương ứng
for (const createdEpic of createdEpics) {
  const stories = createdEpic.originalEpic.stories || [];
  for (const story of stories) {
    pendingStories.push({
      ...story,
      parentEpicKey: createdEpic.epicKey,
      parentEpicId: createdEpic.epicId
    });
  }
}

return [{
  json: {
    step: 7,
    stepName: 'Epic Key Extractor & Story Mapper',
    success: true,
    pendingStories,
    totalStoriesToCreate: pendingStories.length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { cleanDomain, requestHeaders, projectKey, pendingStories } = item;
const createdStories = [];

for (const story of pendingStories) {
  const storyTitle = story.title || 'Untitled Story';
  const storyDesc = story.description || storyTitle;

  const storyFields = {
    project: { key: projectKey },
    summary: storyTitle,
    description: storyDesc,
    issuetype: { name: 'Story' },
    parent: { key: story.parentEpicKey }
  };
  if (story.assigneeId) {
    storyFields.assignee = { accountId: story.assigneeId };
  }

  let resData;
  try {
    const res = await fetch(`${cleanDomain}/rest/api/2/issue`, {
      method: 'POST',
      headers: requestHeaders,
      body: JSON.stringify({ fields: storyFields })
    });
    resData = await res.json().catch(() => ({}));
    if (!res.ok) {
      const errMsg = resData.errorMessages?.join(', ') || JSON.stringify(resData.errors || resData);
      throw new Error(`Jira API (${res.status}): ${errMsg}`);
    }
  } catch (err) {
    return [{
      json: {
        step: 8,
        stepName: 'Story Creation Engine',
        success: false,
        errorMessage: `Lỗi khi tạo Story "${storyTitle}" thuộc Epic ${story.parentEpicKey}: ${err.message}`,
        ...item
      }
    }];
  }

  createdStories.push({
    originalStory: story,
    storyKey: resData.key,
    storyId: resData.id,
    title: storyTitle,
    parentEpicKey: story.parentEpicKey,
    assignee: story.assigneeName || null,
    url: `${cleanDomain}/browse/${resData.key}`
  });
}

return [{
  json: {
    step: 8,
    stepName: 'Story Creation Engine',
    success: true,
    createdStories,
    storiesCount: createdStories.length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { createdStories } = item;
const pendingSubtasks = [];

for (const createdStory of createdStories) {
  const tasks = createdStory.originalStory.tasks || [];
  for (const task of tasks) {
    pendingSubtasks.push({
      ...task,
      parentStoryKey: createdStory.storyKey,
      parentStoryId: createdStory.storyId
    });
  }
}

return [{
  json: {
    step: 9,
    stepName: 'Story Key Extractor & Task Mapper',
    success: true,
    pendingSubtasks,
    totalTasksToCreate: pendingSubtasks.length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { cleanDomain, requestHeaders, projectKey, pendingSubtasks } = item;
const createdTasks = [];

for (const task of pendingSubtasks) {
  const taskTitle = task.title || 'Untitled Subtask';
  const taskDesc = task.description || taskTitle;

  const taskFields = {
    project: { key: projectKey },
    summary: taskTitle,
    description: taskDesc,
    issuetype: { name: 'Subtask' },
    parent: { key: task.parentStoryKey }
  };
  if (task.assigneeId) {
    taskFields.assignee = { accountId: task.assigneeId };
  }

  let resData;
  let createSuccess = false;

  // Thử lần 1 với issuetype "Subtask"
  try {
    const res = await fetch(`${cleanDomain}/rest/api/2/issue`, {
      method: 'POST',
      headers: requestHeaders,
      body: JSON.stringify({ fields: taskFields })
    });
    resData = await res.json().catch(() => ({}));
    if (res.ok) createSuccess = true;
  } catch (err) {}

  // Thử lần 2 với issuetype "Sub-task" (tùy thuộc template cấu hình Jira)
  if (!createSuccess) {
    try {
      taskFields.issuetype = { name: 'Sub-task' };
      const res = await fetch(`${cleanDomain}/rest/api/2/issue`, {
        method: 'POST',
        headers: requestHeaders,
        body: JSON.stringify({ fields: taskFields })
      });
      resData = await res.json().catch(() => ({}));
      if (res.ok) createSuccess = true;
    } catch (err) {}
  }

  if (!createSuccess) {
    return [{
      json: {
        step: 10,
        stepName: 'Subtask Creation Engine',
        success: false,
        errorMessage: `Lỗi khi tạo Subtask "${taskTitle}" thuộc Story ${task.parentStoryKey}`,
        ...item
      }
    }];
  }

  createdTasks.push({
    taskKey: resData.key,
    taskId: resData.id,
    title: taskTitle,
    parentStoryKey: task.parentStoryKey,
    assignee: task.assigneeName || null,
    url: `${cleanDomain}/browse/${resData.key}`
  });
}

return [{
  json: {
    step: 10,
    stepName: 'Subtask Creation Engine',
    success: true,
    createdTasks,
    tasksCount: createdTasks.length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { createdEpics = [], createdStories = [], createdTasks = [] } = item;
const verifiedIssues = [];

for (const e of createdEpics) {
  verifiedIssues.push({
    type: 'Epic',
    key: e.epicKey,
    id: e.epicId,
    title: e.title,
    parent: null,
    assignee: null,
    url: e.url,
    verified: Boolean(e.epicKey)
  });
}

for (const s of createdStories) {
  verifiedIssues.push({
    type: 'Story',
    key: s.storyKey,
    id: s.storyId,
    title: s.title,
    parent: s.parentEpicKey,
    assignee: s.assignee || null,
    url: s.url,
    verified: Boolean(s.storyKey)
  });
}

for (const t of createdTasks) {
  verifiedIssues.push({
    type: 'Subtask',
    key: t.taskKey,
    id: t.taskId,
    title: t.title,
    parent: t.parentStoryKey,
    assignee: t.assignee || null,
    url: t.url,
    verified: Boolean(t.taskKey)
  });
}

return [{
  json: {
    step: 11,
    stepName: 'Issue Verifier & Status Inspector',
    success: true,
    verifiedIssues,
    totalVerified: verifiedIssues.length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { epicsCount = 0, storiesCount = 0, tasksCount = 0 } = item;
const totalIssues = epicsCount + storiesCount + tasksCount;

const executionDurationMs = Date.now() - new Date(item.timestamp).getTime();

const summary = {
  epicsCount,
  storiesCount,
  tasksCount,
  totalIssues,
  executionDurationMs,
  projectKey: item.projectKey,
  status: 'COMPLETED_SUCCESSFULLY'
};

return [{
  json: {
    step: 12,
    stepName: 'Metrics & Summary Calculator',
    success: true,
    summary,
    ...item
  }
}];

const item = $input.first().json;

if (!item.success) {
  return [{
    json: {
      success: false,
      stepFailed: item.step,
      stepName: item.stepName,
      error: item.errorMessage || item.error || 'Quá trình đẩy dữ liệu lên Jira thất bại',
      summary: {
        epicsCount: 0,
        storiesCount: 0,
        tasksCount: 0,
        totalIssues: 0
      },
      createdIssues: []
    }
  }];
}

const { summary, verifiedIssues, projectKey, cleanDomain } = item;

return [{
  json: {
    success: true,
    message: `Đã tạo thành công ${summary.epicsCount} Epic, ${summary.storiesCount} Story, ${summary.tasksCount} Sub-task trên Jira!`,
    summary,
    projectKey,
    jiraDomain: cleanDomain,
    createdIssues: verifiedIssues
  }
}];
